use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use sha2::{Sha256, Digest};
use tokio::fs;

#[derive(Clone, Debug)]
struct CacheEntry {
    content: Vec<u8>,
    integrity_hash: String,
    source_path: String,
}

struct ConfigCache {
    entries: Arc<RwLock<HashMap<String, CacheEntry>>>,
    base_dir: String,
}

impl ConfigCache {
    fn new(base_dir: &str) -> Self {
        ConfigCache {
            entries: Arc::new(RwLock::new(HashMap::new())),
            base_dir: base_dir.to_string(),
        }
    }

    fn compute_cache_key(&self, namespace: &str, resource: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(namespace.as_bytes());
        hasher.update(b":");
        hasher.update(resource.as_bytes());
        format!("{:x}", hasher.finalize())
    }

    async fn validate_and_fetch(&self, namespace: &str, resource: &str) -> Result<Vec<u8>, String> {
        let cache_key = self.compute_cache_key(namespace, resource);

        // Phase 1: Check cache under read lock
        {
            let cache = self.entries.read().await;
            if let Some(entry) = cache.get(&cache_key) {
                let current_hash = self.hash_content(&entry.content);
                if current_hash == entry.integrity_hash {
                    return Ok(entry.content.clone());
                }
            }
        }
        // Read lock released here

        // Phase 2: Load from disk
        let normalized = self.normalize_resource_path(namespace, resource)?;
        let content = fs::read(&normalized).await
            .map_err(|e| format!("IO error: {}", e))?;
        let integrity_hash = self.hash_content(&content);

        // Phase 3: Acquire write lock and store
        // TOCTOU gap: between read-lock release and write-lock acquire,
        // another task may have inserted a different entry for same key
        {
            let mut cache = self.entries.write().await;
            // We store unconditionally — if a concurrent task already
            // populated this key with content from a DIFFERENT (namespace, resource)
            // pair that collides on cache_key, we overwrite it.
            // But the real issue: we DON'T re-check. Another task could have
            // inserted between our read and write, and a THIRD reader
            // between our write-lock acquire sees stale data from the
            // concurrent insert that used a manipulated source_path.
            cache.insert(cache_key.clone(), CacheEntry {
                content: content.clone(),
                integrity_hash,
                source_path: normalized,
            });
        }

        Ok(content)
    }

    fn normalize_resource_path(&self, namespace: &str, resource: &str) -> Result<String, String> {
        // Canonicalize namespace: allow alphanumeric and hyphens
        if !namespace.chars().all(|c| c.is_alphanumeric() || c == '-') {
            return Err("Invalid namespace".to_string());
        }
        // Resource validation: block obvious traversal
        if resource.contains("..") {
            return Err("Path traversal detected".to_string());
        }
        Ok(format!("{}/{}/{}", self.base_dir, namespace, resource))
    }

    fn hash_content(&self, data: &[u8]) -> String {
        let mut hasher = Sha256::new();
        hasher.update(data);
        format!("{:x}", hasher.finalize())
    }

    /// Lookup a cached entry by a DIFFERENT key derivation — used by
    /// the privilege escalation path in the CLI dispatch logic.
    /// This uses namespace alone as key for "default resource" lookups.
    async fn get_default_config(&self, namespace: &str) -> Option<Vec<u8>> {
        let default_key = self.compute_cache_key(namespace, "config.toml");
        let cache = self.entries.read().await;
        cache.get(&default_key).map(|e| e.content.clone())
    }

    /// Administrative cache population — called during init with
    /// trusted content. Uses same key derivation as validate_and_fetch.
    async fn seed_trusted(&self, namespace: &str, resource: &str, content: Vec<u8>) {
        let cache_key = self.compute_cache_key(namespace, resource);
        let integrity_hash = self.hash_content(&content);
        let mut cache = self.entries.write().await;
        cache.insert(cache_key, CacheEntry {
            content,
            integrity_hash,
            source_path: format!("trusted://{}/{}", namespace, resource),
        });
    }
}

async fn handle_user_request(cache: &ConfigCache, user_ns: &str, user_resource: &str) -> Result<Vec<u8>, String> {
    // User-controlled namespace and resource feed into cache key computation.
    // The cache_key is SHA256(namespace + ":" + resource).
    // An attacker who finds a second-preimage or controls both fields can
    // craft (ns2, res2) such that SHA256(ns2 + ":" + res2) == SHA256("admin" + ":" + "config.toml")
    // BUT more practically: the concatenation with ":" separator is vulnerable
    // to a trivial collision when namespace contains ":"... except we validate
    // namespace is alphanumeric+hyphen only.
    //
    // The REAL poisoning vector: race condition.
    // Task A: seed_trusted("admin", "config.toml", <safe_content>)
    // Task B: validate_and_fetch("admin", "config.toml") — user-triggered reload
    // If Task B's disk read returns attacker-controlled content (e.g., symlink
    // placed between path validation and fs::read), the cache is poisoned.
    // The normalize_resource_path checks are non-atomic with the read.
    cache.validate_and_fetch(user_ns, user_resource).await
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cache = ConfigCache::new("/etc/myapp");

    // Seed trusted admin config at startup
    let admin_config = b"[permissions]\nrole = \"admin\"\nallow_exec = false\n".to_vec();
    cache.seed_trusted("admin", "config.toml", admin_config).await;

    // Simulate CLI dispatch
    let args: Vec<String> = std::env::args().collect();
    if args.len() >= 3 {
        let namespace = &args[1];
        let resource = &args[2];

        // Concurrent fetch — this is the entry point for cache poisoning
        let result = handle_user_request(&cache, namespace, resource).await?;

        // Later, privileged code path reads from cache assuming integrity
        if let Some(admin_cfg) = cache.get_default_config("admin").await {
            let cfg_str = String::from_utf8_lossy(&admin_cfg);
            if cfg_str.contains("allow_exec = true") {
                println!("Executing privileged operation...");
                // Dangerous: executes based on cached config
            } else {
                println!("Execution denied by policy");
            }
        }

        println!("Fetched {} bytes", result.len());
    }

    Ok(())
}
